import enum
import types

import ulrmm.constants as c


def norm(v):
    if isinstance(v, type) and issubclass(v, enum.Enum):
        return ("enum", v.__name__, [(m.name, m.value) for m in v])
    if isinstance(v, (types.FunctionType, types.ModuleType, type)):
        return ("callable", getattr(v, "__name__", str(v)))
    if isinstance(v, (set, frozenset)):
        return sorted(map(str, v))
    return v


names = sorted(n for n in dir(c) if not n.startswith("_"))
print(len(names), "public names")
for n in names:
    print(n, "=", repr(norm(getattr(c, n)))[:600])

