# DNS answer changes between the check and the connection (rebinding)
calls = []
real = socket.getaddrinfo


def flip(host, port, *a, **k):
    if host == "rebind.test":
        calls.append(host)
        ip = "93.184.216.34" if len(calls) == 1 else "127.0.0.1"
        return [(socket.AF_INET, socket.SOCK_STREAM, 6, "", (ip, port or 0))]
    return real(host, port, *a, **k)


with mock.patch("socket.getaddrinfo", flip):
    try:
        r = cu._run_url_rest_action(url="http://rebind.test:9199/", method="get", body="{}", headers="{}")
        print("rebinding: reached", r.status_code, "resolutions", len(calls))
    except Exception as e:
        print("rebinding: refused", type(e).__name__, str(e)[:90], "resolutions", len(calls))

